export function decideRetry(input) {
  return { retry: false, delayMs: 0, reason: 'not-implemented' };
}

import assert from 'node:assert/strict';
import test from 'node:test';
import { decideRetry } from '../src/retry-policy.mjs';

const nowMs = Date.UTC(2015, 9, 21, 7, 28, 0);
const base = { method: 'GET', status: 503, attempt: 1, nowMs };
const stop = reason => ({ retry: false, delayMs: 0, reason });
const again = delayMs => ({ retry: true, delayMs, reason: 'transient' });

test('cancellation takes precedence over method, status, and budget', () => {
  assert.deepEqual(decideRetry({ ...base, aborted: true, method: 'POST', attempt: 9 }), stop('canceled'));
  assert.deepEqual(decideRetry({ ...base, errorName: 'AbortError' }), stop('canceled'));
});

test('unsafe purchase methods never retry, even on supplier failures', () => {
  for (const method of ['POST', 'PATCH', 'PUT', 'DELETE']) {
    assert.deepEqual(decideRetry({ ...base, method }), stop('unsafe-method'));
  }
  assert.deepEqual(decideRetry({ ...base, method: 'head' }), again(250));
  assert.deepEqual(decideRetry({ ...base, method: 'get', attempt: 2 }), again(500));
});

test('retry budget applies to failed attempts, not just successful attempts', () => {
  for (const attempt of [3, 4, 100]) assert.deepEqual(decideRetry({ ...base, attempt }), stop('exhausted'));
});

test('status and transport error classification preserves HTTP semantics', () => {
  for (const status of [429, 503]) assert.deepEqual(decideRetry({ ...base, status }), again(250));
  for (const status of [200, 301, 400, 401, 404, 500, 502]) assert.deepEqual(decideRetry({ ...base, status }), stop('not-retryable'));
  for (const errorName of ['TypeError', 'TimeoutError']) {
    assert.deepEqual(decideRetry({ ...base, status: undefined, errorName }), again(250));
  }
  assert.deepEqual(decideRetry({ ...base, status: 404, errorName: 'TypeError' }), stop('not-retryable'));
  assert.deepEqual(decideRetry({ ...base, status: undefined, errorName: 'SyntaxError' }), stop('not-retryable'));
});

test('Retry-After supports integer seconds, valid HTTP dates, clamp, and past dates', () => {
  for (const [retryAfter, expected] of [
    ['0', 0], [' 2 ', 2000], ['999', 5000],
    ['Wed, 21 Oct 2015 07:28:03 GMT', 3000],
    ['Wed, 21 Oct 2015 07:28:10 GMT', 5000],
    ['Wed, 21 Oct 2015 07:27:59 GMT', 0],
  ]) assert.deepEqual(decideRetry({ ...base, retryAfter }), again(expected), retryAfter);
});

test('malformed Retry-After falls back to bounded exponential delay', () => {
  for (const retryAfter of ['', '-1', '+2', '1.5', '2ms', 'tomorrow', '2015-10-21', 'Wed, 99 Oct 2015 07:28:00 GMT', '9'.repeat(400)]) {
    assert.deepEqual(decideRetry({ ...base, attempt: 2, retryAfter }), again(500), retryAfter);
  }
});

test('decision is deterministic and cannot mutate caller state', () => {
  const input = Object.freeze({ ...base, retryAfter: '2' });
  const first = decideRetry(input);
  assert.deepEqual(first, again(2000));
  assert.deepEqual(decideRetry(input), first);
  assert.deepEqual(input, { ...base, retryAfter: '2' });
});
